mgc_code:
def _ValidateFSM(self):
    """Checks state names and destinations for validity.

    Each destination state must exist, be a valid name and
    not be a reserved name.
    There must be a 'Start' state and if 'EOF' or 'End' states are specified,
    they must be empty.

    Returns:
      True if FSM is valid.

    Raises:
      TextFSMTemplateError: If any state definitions are invalid.
    """
    if not self.states:
      raise TextFSMTemplateError('FSM has no states')

    if 'Start' not in self.states:
      raise TextFSMTemplateError('FSM has no Start state')

    if 'End' in self.states and self.states['End']:
      raise TextFSMTemplateError('End state must be empty')

    if 'EOF' in self.states and self.states['EOF']:
      raise TextFSMTemplateError('EOF state must be empty')

    for state in self.states:
      if state in _RESERVED_NAMES:
        raise TextFSMTemplateError('%s is a reserved name' % state)

      if state not in self.states:
        raise TextFSMTemplateError('%s is not a valid state' % state)

      if state == 'Start':
        continue

      if not self.states[state]:
        continue

      for dest in self.states[state]:
        if dest not in self.states:
          raise TextFSMTemplateError('%s is not a valid state' % dest)

        if dest == 'End':
          raise TextFSMTemplateError('End state must be empty')

        if dest == 'EOF':
          raise TextFSMTemplateError('EOF state must be empty')

        if dest == 'Start':
          raise TextFSMTemplateError('Start state cannot be a destination')

    return True

