def normalize(self):
    """
    Normalizes this vector.
    """
    return self.normalized()

def dot(self, other):
    """
    Returns the dot product of this vector and the other vector.
    """
    return self.x * other.x + self.y * other.y

def cross(self, other):
    """
    Returns the cross product of this vector and the other vector.
    """
    return self.x * other.y - self.y * other.x

def angle(self, other):
    """
    Returns the angle between this vector and the other vector.
    """
    return math.acos(self.dot(other) / (self.length() * other.length()))

def rotate(self, angle):
    """
    Rotates this vector by the given angle.
    """
    return Vector2(self.x * math.cos(angle) - self.y * math.sin(angle),
                   self.x * math.sin(angle) + self.y * math.cos(angle))

def rotate_to(self, other):
    """
    Rotates this vector to point to the other vector.
    """
    return self.rotate(self.angle(other))

def lerp(self, other, t):
    """
    Linearly interpolates between this vector and the other vector.
    """
    return self + (other - self) * t

def lerp_to(self, other, t):
    """
    Linearly interpolates this vector to point to the other vector.
    """
    return self.lerp(other, t)

def distance(self, other):
    """
    Returns the distance between this vector and the other vector.
    """
    return (self - other).length()

def distance_squared(self, other):
    """
    Returns the squared distance between this vector and the other vector.
    """
    return (self - other).length_squared()

def __add__(self, other):
