        The name of the methods in the Checker class should start with "check_" for this
        method to find them.
        """
        checks = []
        for check in dir(checkclass):
            if check.startswith('check_'):
                if check not in skip_checks:
                    checks.append(getattr(checkclass, check))
        return checks

